static void test_configure_640x480_pixel_register(void)
{
  uint32_t pixel_reg;
  uint32_t x_pixel;
  uint32_t y_pixel;
  uint32_t frame_blk;

  bk7258_sim_reset();

  /* 640/8=80, 480/8=60, frame_blk=(80*60)/2=2400, matching bk_dvp.c's
   * "yuv_mode_config.x_pixel = config->width / 8" convention (the /8
   * conversion happens at the application layer, not in the register
   * itself -- see bk7258_yuv_buf.c's file header comment citing
   * yuv_buf_hal_set_config_common(), which writes config->x_pixel
   * directly with no further scaling). */
  bk7258_yuv_buf_configure(640, 480);

  pixel_reg = bk7258_sim_peek32(TEST_YUV_BUF_PIXEL);
  x_pixel = pixel_reg & 0xffu;
  y_pixel = (pixel_reg >> 8) & 0xffu;
  frame_blk = (pixel_reg >> 16) & 0xffffu;

  CHECK(x_pixel == 80u,
        "expected x_pixel = 640/8 = 80, got %u", x_pixel);
  CHECK(y_pixel == 60u,
        "expected y_pixel = 480/8 = 60, got %u", y_pixel);
  CHECK(frame_blk == 2400u,
        "expected frame_blk = (80*60)/2 = 2400, got %u", frame_blk);
}

static void test_configure_other_resolutions(void)
{
  uint32_t pixel_reg;

  bk7258_sim_reset();
  bk7258_yuv_buf_configure(864, 480);
  pixel_reg = bk7258_sim_peek32(TEST_YUV_BUF_PIXEL);
  CHECK((pixel_reg & 0xffu) == 108u,
        "expected x_pixel = 864/8 = 108 for 864x480, got %u",
        pixel_reg & 0xffu);
  CHECK(((pixel_reg >> 8) & 0xffu) == 60u,
        "expected y_pixel = 480/8 = 60 for 864x480, got %u",
        (pixel_reg >> 8) & 0xffu);

  bk7258_sim_reset();
  bk7258_yuv_buf_configure(1280, 720);
  pixel_reg = bk7258_sim_peek32(TEST_YUV_BUF_PIXEL);
  CHECK((pixel_reg & 0xffu) == 160u,
        "expected x_pixel = 1280/8 = 160 for 1280x720, got %u",
        pixel_reg & 0xffu);
  CHECK(((pixel_reg >> 8) & 0xffu) == 90u,
        "expected y_pixel = 720/8 = 90 for 1280x720, got %u",
        (pixel_reg >> 8) & 0xffu);
}

static void test_configure_writes_fixed_psram_line_buffer_address(void)
{
  bk7258_sim_reset();

  /* YUV direct-capture mode hard-codes em_base_addr/emr_base_addr to
   * SOC_PSRAM_DATA_BASE regardless of resolution -- this is not an
   * application-supplied address (see bk7258_yuv_buf.c's file header
   * comment citing yuv_buf_hal_set_yuv_mode_config()'s "yuv_mode set
   * em_base_addr as psram" comment in the upstream reference). */
  bk7258_yuv_buf_configure(640, 480);

  CHECK(bk7258_sim_peek32(TEST_YUV_BUF_EM_BASE_ADDR) ==
        TEST_PSRAM_LINE_BUF_ADDR,
        "expected em_base_addr to be the fixed PSRAM address 0x%x, "
        "got 0x%x", TEST_PSRAM_LINE_BUF_ADDR,
        bk7258_sim_peek32(TEST_YUV_BUF_EM_BASE_ADDR));
  CHECK(bk7258_sim_peek32(TEST_YUV_BUF_EMR_BASE_ADDR) ==
        TEST_PSRAM_LINE_BUF_ADDR,
        "expected emr_base_addr to also be the fixed PSRAM address "
        "0x%x, got 0x%x", TEST_PSRAM_LINE_BUF_ADDR,
        bk7258_sim_peek32(TEST_YUV_BUF_EMR_BASE_ADDR));

  bk7258_sim_reset();
  bk7258_yuv_buf_configure(1280, 720);
  CHECK(bk7258_sim_peek32(TEST_YUV_BUF_EM_BASE_ADDR) ==
        TEST_PSRAM_LINE_BUF_ADDR,
        "expected em_base_addr to remain the fixed PSRAM address "
        "regardless of resolution (1280x720 case), got 0x%x",
