/****************************************************************************
 * board/beken/chips/bk7258/sim_tests/test_i2c_bitbang.c
 *
 * Unit tests for bk7258_gc2145_i2c_bitbang.c, compiled against the real
 * production source (unmodified).
 *
 * Focus: the read path (bk7258_i2c1_read_reg()), which is newly written
 * timing-sensitive code.  A malformed read would not just fail to return
 * a chip ID -- a botched repeated-START can leave the slave mid-transaction
 * and corrupt the 585-entry initialization table written right after it,
 * so the bus waveform is checked here on the desktop before it ever runs
 * on hardware.
 *
 * Strategy: instead of a full slave state machine, the write hook records
 * every SCL/SDA transition the driver makes, and the recording is then
 * decoded into bus events (START / STOP / bit / ACK-window level).  That
 * is enough to assert the structural properties a correct
 * write-pointer/repeated-START/read transaction must have, without
 * depending on the sampling behaviour of a mock slave.  The read hook
 * simply holds SDA low so every ACK is seen as acknowledged and read data
 * bits come back as zero.
 *
 * SPDX-License-Identifier: Apache-2.0
 ****************************************************************************/

#include <stdio.h>
#include <string.h>

#include "sim_stubs.h"
#include "hardware/bk7258_gpio.h"
#include "bk7258_gpio.h"
#include "bk7258_gc2145_i2c_bitbang.h"

static int g_failures;

#define CHECK(cond, ...) \
  do \
    { \
      if (!(cond)) \
        { \
          g_failures++; \
          printf("FAIL %s:%d: ", __func__, __LINE__); \
          printf(__VA_ARGS__); \
          printf("\n"); \
        } \
    } \
  while (0)

/* GPIO42 = SCL, GPIO43 = SDA, per bk7258_gc2145_i2c_bitbang.c. */

#define BITBANG_SCL_PIN 42u
#define BITBANG_SDA_PIN 43u

#define MAX_EVENTS 4096

enum bus_event_e
{
  EV_START,
  EV_STOP,
  EV_BIT,          /* value = SDA level sampled on the SCL rising edge */
};

struct bus_event_s
{
  enum bus_event_e type;
  int value;
};

static struct bus_event_s g_events[MAX_EVENTS];
static int g_event_count;
static bool g_scl;
static bool g_sda;

static void record(enum bus_event_e type, int value)
{
  if (g_event_count < MAX_EVENTS)
    {
      g_events[g_event_count].type = type;
      g_events[g_event_count].value = value;
      g_event_count++;
    }
}

/* Level actually on the wire: the master drives it through
 * BK7258_GPIO_OUTPUT, and the read hook below mirrors the released state
 * into the same bit so one wire never looks like two states.
 */

static bool wire_level(unsigned int pin)
{
  return (bk7258_sim_peek32(BK7258_GPIO_CFG(pin)) &
          BK7258_GPIO_OUTPUT) != 0;
}

static void bus_write_hook(uintptr_t addr, uint32_t value, void *arg)
{
  bool scl = g_scl;
  bool sda = g_sda;

  (void)arg;

  if (addr == BK7258_GPIO_CFG(BITBANG_SCL_PIN))
    {
      scl = (value & BK7258_GPIO_OUTPUT) != 0;
    }
  else if (addr == BK7258_GPIO_CFG(BITBANG_SDA_PIN))
    {
      sda = (value & BK7258_GPIO_OUTPUT) != 0;
    }
  else
    {
      return;
    }

  /* SDA transition while SCL is high: START (high->low) or STOP
   * (low->high).
   */

  if (scl && g_scl && sda != g_sda)
    {
      record(sda ? EV_STOP : EV_START, 0);
    }

  /* SCL rising edge: this is where a slave samples, so this is the bit
   * the master is presenting.
   */

  if (scl && !g_scl)
    {
      record(EV_BIT, sda ? 1 : 0);
    }

  g_scl = scl;
  g_sda = sda;
}

/* Hold SDA low whenever the driver releases it to input, so every ACK
 * window reads as ACK and every read data bit comes back 0.  The level is
 * mirrored into the stored value as well, because the write hook above
 * decides START/STOP from the stored bit.
 */

static uint32_t bus_read_hook(uintptr_t addr, uint32_t stored_value,
                              void *arg)
{
  (void)arg;

  if (addr != BK7258_GPIO_CFG(BITBANG_SDA_PIN))
    {
      return stored_value;
    }

  if ((stored_value & BK7258_GPIO_INPUT_ENABLE) == 0)
    {
      return stored_value;
    }

  g_sda = false;
  return stored_value & ~(BK7258_GPIO_INPUT | BK7258_GPIO_OUTPUT);
}

static void bus_reset(void)
{
  bk7258_sim_reset();
  memset(g_events, 0, sizeof(g_events));
  g_event_count = 0;
  g_scl = false;
  g_sda = false;
  bk7258_sim_set_write_hook(bus_write_hook, NULL);
  bk7258_sim_set_read_hook(bus_read_hook, NULL);
  bk7258_i2c1_init();

  /* init() itself idles the bus; only transaction events matter. */

  g_event_count = 0;
  g_scl = wire_level(BITBANG_SCL_PIN);
  g_sda = wire_level(BITBANG_SDA_PIN);
}

static int count_events(enum bus_event_e type)
{
  int i;
  int n = 0;

  for (i = 0; i < g_event_count; i++)
    {
      if (g_events[i].type == type)
        {
          n++;
        }
    }

  return n;
}

/* Decodes the recorded bit stream into bytes, 9 bits per byte (8 data +
 * 1 ACK window).  Returns the number of bytes decoded; acks[] receives
 * the level seen in each ACK window.
 */

static int decode_bytes(uint8_t *bytes, int *acks, int max)
{
  int i;
  int n = 0;
  int bit = 0;
  uint8_t cur = 0;

  for (i = 0; i < g_event_count && n < max; i++)
    {
      if (g_events[i].type == EV_START)
        {
          bit = 0;
          cur = 0;
          continue;
        }

      if (g_events[i].type != EV_BIT)
        {
          continue;
        }

      if (bit < 8)
        {
          cur = (uint8_t)((cur << 1) | (g_events[i].value ? 1 : 0));
          bit++;
        }
      else
        {
          bytes[n] = cur;
          acks[n] = g_events[i].value;
          n++;
          bit = 0;
          cur = 0;
        }
    }

  return n;
}

/****************************************************************************
 * write_reg
 ****************************************************************************/

static void test_write_reg_bus_sequence(void)
{
  uint8_t bytes[8];
  int acks[8];
  int n;
  bool ok;

  bus_reset();

  ok = bk7258_i2c1_write_reg(0x3Cu, 0x42u, 0x99u);

  CHECK(ok, "expected write_reg to report success when the slave ACKs");
  CHECK(count_events(EV_START) == 1,
        "expected exactly 1 START in a register write, got %d",
        count_events(EV_START));
  CHECK(count_events(EV_STOP) == 1,
        "expected exactly 1 STOP in a register write, got %d",
        count_events(EV_STOP));

  n = decode_bytes(bytes, acks, 8);
  CHECK(n == 3, "expected 3 bytes (addr+W, reg, data), got %d", n);
  if (n == 3)
    {
      CHECK(bytes[0] == 0x78u,
            "expected address byte 0x3C<<1 = 0x78, got 0x%02x", bytes[0]);
      CHECK(bytes[1] == 0x42u,
            "expected register byte 0x42, got 0x%02x", bytes[1]);
      CHECK(bytes[2] == 0x99u,
            "expected data byte 0x99, got 0x%02x", bytes[2]);
    }
}

/****************************************************************************
 * read_reg
 ****************************************************************************/

static void test_read_reg_bus_sequence(void)
{
  uint8_t bytes[8];
  int acks[8];
  uint8_t value = 0xAAu;
  int n;
  bool ok;

  bus_reset();

  ok = bk7258_i2c1_read_reg(0x3Cu, 0xF0u, &value);

  CHECK(ok, "expected read_reg to succeed when the slave ACKs");

  /* A register read is write-pointer, repeated START, read: two STARTs
   * and exactly one STOP.  An extra STOP between the two phases would
   * let the slave forget the register pointer.
   */

  CHECK(count_events(EV_START) == 2,
        "expected 2 STARTs (initial + repeated) in a register read, got %d",
        count_events(EV_START));
  CHECK(count_events(EV_STOP) == 1,
        "expected exactly 1 STOP, i.e. no STOP before the repeated START, "
        "got %d", count_events(EV_STOP));

  n = decode_bytes(bytes, acks, 8);
  CHECK(n == 4,
        "expected 4 byte slots (addr+W, reg, addr+R, data), got %d", n);
  if (n == 4)
    {
      CHECK(bytes[0] == 0x78u,
            "expected write address byte 0x78, got 0x%02x", bytes[0]);
      CHECK(bytes[1] == 0xF0u,
            "expected register byte 0xF0, got 0x%02x", bytes[1]);
      CHECK(bytes[2] == 0x79u,
            "expected read address byte 0x3C<<1|1 = 0x79, got 0x%02x",
            bytes[2]);

      /* Single-byte read: the master must NACK (drive SDA high) so the
       * slave releases the bus before STOP.
       */

      CHECK(acks[3] == 1,
            "expected the master to NACK the only data byte (SDA high in "
            "the 9th window), got %d", acks[3]);
    }

  CHECK(value == 0x00u,
        "expected the value read back from a slave holding SDA low to be "
        "0x00, got 0x%02x", value);
}

static void test_read_reg_rejects_null_value(void)
{
  bus_reset();

  CHECK(bk7258_i2c1_read_reg(0x3Cu, 0xF0u, NULL) == false,
        "expected read_reg to reject a NULL output pointer");
  CHECK(g_event_count == 0,
        "expected no bus activity when the arguments are invalid, got %d "
        "events", g_event_count);
}

static void test_read_reg_reports_address_nack(void)
{
  uint8_t value = 0x5Au;

  bus_reset();

  /* No read hook: SDA released reads back as driven high -> NACK. */

  bk7258_sim_set_read_hook(NULL, NULL);

  CHECK(bk7258_i2c1_read_reg(0x3Cu, 0xF0u, &value) == false,
        "expected read_reg to fail when the address byte is NACKed");
  CHECK(count_events(EV_STOP) >= 1,
        "expected the bus to be released with a STOP after a NACK, so the "
        "next transaction can start cleanly");
}

int main(void)
{
  test_write_reg_bus_sequence();
  test_read_reg_bus_sequence();
  test_read_reg_rejects_null_value();
  test_read_reg_reports_address_nack();

  if (g_failures == 0)
    {
      printf("PASS: all bk7258_gc2145_i2c_bitbang.c tests passed\n");
      return 0;
    }

  printf("FAILED: %d assertion(s) failed\n", g_failures);
  return 1;
}

